cat > /data/data/com.termux/files/home/.termux/tasker/hidkey.sh <<'EOF'
#!/data/data/com.termux/files/usr/bin/bash
set -euo pipefail

FIFO="/data/local/tmp/pixel_keyboard.fifo"
STATE="/data/local/tmp/pixel_keyboard.modstate"

token="${1:-}"
[ -n "$token" ] || exit 0

# Modifier bits (HID): Ctrl=0x01, Shift=0x02, Alt=0x04, GUI=0x08
# (Left variants; sticky toggles)
mod=0
if [ -f "$STATE" ]; then
  mod="$(cat "$STATE")"
fi

toggle_mod() {
  local bit="$1"
  if (( (mod & bit) != 0 )); then
    mod=$(( mod & ~bit ))
  else
    mod=$(( mod | bit ))
  fi
  echo "$mod" > "$STATE"
}

# Emit a single HID keyboard report (8 bytes):
# [mod][0][k1][k2][k3][k4][k5][k6]
emit_key() {
  local key="$1"
  # press
  printf '{"type":"keyboard","report":[%d,0,%d,0,0,0,0,0]}\n' "$mod" "$key" > "$FIFO"
  # release (keep modifiers as-is)
  printf '{"type":"keyboard","report":[%d,0,0,0,0,0,0,0]}\n' "$mod" > "$FIFO"
}

emit_release_all() {
  mod=0
  echo "$mod" > "$STATE"
  printf '{"type":"keyboard","report":[0,0,0,0,0,0,0,0]}\n' > "$FIFO"
}

case "$token" in
  CTRL)  toggle_mod 1 ;;
  SHIFT) toggle_mod 2 ;;
  ALT)   toggle_mod 4 ;;
  GUI|WIN|META) toggle_mod 8 ;;

  LEFT)  emit_key 0x50 ;;
  RIGHT) emit_key 0x4F ;;
  UP)    emit_key 0x52 ;;
  DOWN)  emit_key 0x51 ;;

  ESC)   emit_key 0x29 ;;
  TAB)   emit_key 0x2B ;;
  ENTER) emit_key 0x28 ;;
  BACKSPACE|BKSP) emit_key 0x2A ;;
  DEL|DELETE) emit_key 0x4C ;;
  INS|INSERT) emit_key 0x49 ;;
  HOME)  emit_key 0x4A ;;
  END)   emit_key 0x4D ;;
  PGUP)  emit_key 0x4B ;;
  PGDN)  emit_key 0x4E ;;

  CLEAR) emit_release_all ;;

  *)
    # If token looks like a single character, try to map basic a-z/0-9 quickly (optional).
    # Otherwise: ignore.
    exit 0
    ;;
esac
EOF
chmod 700 /data/data/com.termux/files/home/.termux/tasker/hidkey.sh
